PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS index_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS binary_artifacts(elf_sha256 TEXT PRIMARY KEY,architecture TEXT,bitness INTEGER,endianness TEXT,abi TEXT,elf_flags INTEGER);
CREATE TABLE IF NOT EXISTS binary_releases(id TEXT PRIMARY KEY,elf_sha256 TEXT REFERENCES binary_artifacts,firmware_version TEXT,role TEXT,original_path TEXT,provenance TEXT);
CREATE TABLE IF NOT EXISTS binary_ranges(id TEXT PRIMARY KEY,elf_sha256 TEXT REFERENCES binary_artifacts,section_index INTEGER,section_name TEXT,address INTEGER,size INTEGER,file_offset INTEGER,storage_kind TEXT,content_sha256 TEXT,instruction_mode TEXT,extent_evidence TEXT);
CREATE TABLE IF NOT EXISTS external_providers(id TEXT PRIMARY KEY,metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS symbol_occurrences(id TEXT PRIMARY KEY,native_id TEXT NOT NULL,catalog_anchor TEXT NOT NULL,elf_sha256 TEXT REFERENCES binary_artifacts,original_mangled TEXT,demangled TEXT,symbol_kind TEXT,binding TEXT,section_index TEXT,original_address INTEGER,original_size INTEGER,range_id TEXT REFERENCES binary_ranges,strategy TEXT,provider_id TEXT REFERENCES external_providers,binding_status TEXT,provider_binding TEXT);
CREATE INDEX IF NOT EXISTS occurrence_identity ON symbol_occurrences(elf_sha256,original_mangled);
CREATE INDEX IF NOT EXISTS range_location ON binary_ranges(elf_sha256,address);
CREATE INDEX IF NOT EXISTS occurrence_range ON symbol_occurrences(range_id);
CREATE INDEX IF NOT EXISTS occurrence_native ON symbol_occurrences(native_id);
CREATE TABLE IF NOT EXISTS signature_groups(id TEXT PRIMARY KEY,mangling_scheme TEXT,abi_family TEXT,original_mangled TEXT,encoded_signature_equal INTEGER,original_return_type_verified INTEGER);
CREATE TABLE IF NOT EXISTS signature_members(group_id TEXT REFERENCES signature_groups,occurrence_id TEXT REFERENCES symbol_occurrences,PRIMARY KEY(group_id,occurrence_id));
CREATE TABLE IF NOT EXISTS code_content_groups(id TEXT PRIMARY KEY,architecture TEXT,bitness INTEGER,endianness TEXT,instruction_mode TEXT,size INTEGER,content_sha256 TEXT);
CREATE TABLE IF NOT EXISTS code_content_members(group_id TEXT REFERENCES code_content_groups,occurrence_id TEXT REFERENCES symbol_occurrences,PRIMARY KEY(group_id,occurrence_id));
CREATE TABLE IF NOT EXISTS payload_contents(id TEXT PRIMARY KEY,size INTEGER,content_sha256 TEXT,object_path TEXT NOT NULL,UNIQUE(size,content_sha256));
CREATE TABLE IF NOT EXISTS payload_occurrences(id TEXT PRIMARY KEY,range_id TEXT REFERENCES binary_ranges,content_id TEXT REFERENCES payload_contents,extent_evidence TEXT,interpretation TEXT);
CREATE INDEX IF NOT EXISTS payload_range ON payload_occurrences(range_id);
CREATE TABLE IF NOT EXISTS payload_transformations(id TEXT PRIMARY KEY,input_content TEXT REFERENCES payload_contents,output_content TEXT REFERENCES payload_contents,transform TEXT,evidence_refs TEXT);
CREATE TABLE IF NOT EXISTS dependency_observations(occurrence_id TEXT PRIMARY KEY REFERENCES symbol_occurrences,coverage TEXT NOT NULL,observations TEXT NOT NULL,blockers TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equivalence_decisions(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,revision INTEGER NOT NULL,equivalence_kind TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('candidate','verified','rejected','blocked')),verification_scope TEXT NOT NULL,reason TEXT NOT NULL,members TEXT NOT NULL,evidence_refs TEXT NOT NULL,producer_identity TEXT NOT NULL,producer_sha256 TEXT NOT NULL,policy_version TEXT NOT NULL,input_generation TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(subject_id,revision));
CREATE TRIGGER IF NOT EXISTS decisions_no_update BEFORE UPDATE ON equivalence_decisions BEGIN SELECT RAISE(ABORT,'decisions append only'); END;
CREATE TRIGGER IF NOT EXISTS decisions_no_delete BEFORE DELETE ON equivalence_decisions BEGIN SELECT RAISE(ABORT,'decisions append only'); END;
CREATE TABLE IF NOT EXISTS implementation_groups(id TEXT PRIMARY KEY,decision_id TEXT REFERENCES equivalence_decisions,representative TEXT REFERENCES symbol_occurrences);
CREATE TABLE IF NOT EXISTS implementation_members(group_id TEXT REFERENCES implementation_groups,occurrence_id TEXT REFERENCES symbol_occurrences,PRIMARY KEY(group_id,occurrence_id));
CREATE INDEX IF NOT EXISTS implementation_occurrence ON implementation_members(occurrence_id);
CREATE TABLE IF NOT EXISTS reconstruction_work_items(id TEXT PRIMARY KEY,work_kind TEXT NOT NULL,subject_id TEXT NOT NULL,decision_id TEXT REFERENCES equivalence_decisions,status TEXT NOT NULL DEFAULT 'todo',representative TEXT REFERENCES symbol_occurrences,UNIQUE(work_kind,subject_id));
CREATE TABLE IF NOT EXISTS work_item_members(work_item_id TEXT REFERENCES reconstruction_work_items,occurrence_id TEXT REFERENCES symbol_occurrences,PRIMARY KEY(work_item_id,occurrence_id));
CREATE TABLE IF NOT EXISTS work_claims(id TEXT PRIMARY KEY,work_item_id TEXT REFERENCES reconstruction_work_items,owner TEXT NOT NULL,packet_path TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','completed','released','conflict')),generation TEXT NOT NULL,decision_id TEXT,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_claim ON work_claims(work_item_id) WHERE state='active';
CREATE INDEX IF NOT EXISTS claim_owner ON work_claims(state,owner);
CREATE TABLE IF NOT EXISTS claim_history(id INTEGER PRIMARY KEY,claim_id TEXT REFERENCES work_claims,state TEXT,reason TEXT,observations TEXT,created_at TEXT);
CREATE TRIGGER IF NOT EXISTS claim_history_no_update BEFORE UPDATE ON claim_history BEGIN SELECT RAISE(ABORT,'claim history append only'); END;
CREATE TRIGGER IF NOT EXISTS claim_history_no_delete BEFORE DELETE ON claim_history BEGIN SELECT RAISE(ABORT,'claim history append only'); END;
CREATE TABLE IF NOT EXISTS work_results(id TEXT PRIMARY KEY,work_item_id TEXT REFERENCES reconstruction_work_items,covered_occurrences TEXT,common_checks TEXT,individual_checks TEXT,evidence_refs TEXT,input_generation TEXT,decision_id TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS planning_conflicts(id INTEGER PRIMARY KEY,subject_id TEXT,reason TEXT,claims TEXT,created_at TEXT);
CREATE INDEX IF NOT EXISTS code_member_occurrence ON code_content_members(occurrence_id);
CREATE INDEX IF NOT EXISTS signature_member_occurrence ON signature_members(occurrence_id);
CREATE INDEX IF NOT EXISTS member_work_lookup ON work_item_members(occurrence_id);
